+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit; the ingredients are consumed with ref `sale:<ticket>`. A ticket is
+// imported once; a batch of sales is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sales lines { row, ticket, soldAt, dishId, qty } (soldAt an ISO
+ * instant in UTC). Lines of tickets already imported are skipped. Checks
+ * every line first and throws (changing nothing) naming the row; then
+ * consumes the ingredients. Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines, { at }) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const planned = fresh.map((l) => {
+    let dish;
+    try {
+      dish = getDish(store, l.dishId);
+    } catch {
+      throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    }
+    return { ...l, uses: scaled(getRecipe(store, dish.recipeId), l.qty) };
+  });
+  const need = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const total = round3((need.get(u.itemId) ?? 0) + u.qty);
+      need.set(u.itemId, total);
+      const item = getItem(store, u.itemId);
+      const available = onHand(store, u.itemId);
+      if (available < total)
+        throw new AppError("sale_not_enough_stock", { row: p.row, item: item.name, available: round3(available), unit: item.unit });
+    }
+  }
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const p of planned) {
+    for (const u of p.uses) if (u.qty > 0) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses, importedAt: at });
+    tickets.add(p.ticket);
+    dishes += p.qty;
+  }
+  return { tickets: tickets.size, dishes };
+}
